=====
// git-remote-entire is a Git remote helper that allows using entire:// URLs.
// Usage: git clone entire://host.com/project/repo
//
// Git invokes this binary as: git-remote-entire <remote-name> <url>
// The helper proxies Git smart HTTP protocol to the Entire server with
// automatic authentication.
//
// Node discovery: the host in the URL is the cluster entry domain
// (fronted by a load balancer). The helper sends info/refs there on a
// cold start; the server either serves the request directly or 307s to
// a hosting replica, and every response carries an X-Entire-Replicas
// header listing the replica set. The helper caches that set at
// ~/.cache/entire/nodes.json and sends subsequent requests (pack data,
// later info/refs) direct to a cached replica.
//
// The bulk of the helper's logic lives under internal/:
//
//   - internal/githelper     — git remote helper protocol loop
//   - internal/entire/transport — HTTP transport with failover
//   - internal/entire/auth   — scoped-token mint + context resolution
//   - internal/entire/replicas — replica cache
//   - internal/gitproto, pktline — git wire protocol helpers
//   - internal/httpdebug, debuglog — debug & redaction
//
// This file is just the CLI wrapper: parse argv, wire authentication,
// dial the transport, hand stdin/stdout to the protocol loop.
package main

import (
	"context"
	"fmt"
	"net/http"
	"net/url"
	"os"
	"os/signal"
	"syscall"
	"time"

	"entire.io/client"
	"entire.io/client/clilogin"
	"entire.io/client/contexts"
	"entire.io/client/httpclient"
	"entire.io/internal/remotehelper/debuglog"
	"entire.io/internal/remotehelper/entire/auth"
	"entire.io/internal/remotehelper/entire/replicas"
	"entire.io/internal/remotehelper/entire/transport"
	"entire.io/internal/remotehelper/githelper"
)

func main() {
	if len(os.Args) < 3 {
		fatal("usage: git-remote-entire <remote-name> <url>")
	}

	skipTLS := os.Getenv("ENTIRE_TLS_SKIP_VERIFY") == "true"
	rawURL := os.Args[2]

	debuglog.Printf("invoked: remote=%s url=%s", os.Args[1], rawURL)
	if skipTLS {
		debuglog.Printf("ENTIRE_TLS_SKIP_VERIFY=true: TLS verification disabled for all HTTP clients")
	}

	parsedURL, err := url.Parse(rawURL)
	if err != nil {
		fatal("invalid URL %q: %v", rawURL, err)
	}
	if parsedURL.Scheme != "entire" {
		fatal("unsupported URL scheme %q (expected 'entire')", parsedURL.Scheme)
	}
	if parsedURL.Host == "" {
		fatal("missing host in URL %q", rawURL)
	}

	ctx, stopSignals := installSignalHandler()
	defer stopSignals()

	clusterHost := parsedURL.Host
	debuglog.Printf("clusterHost=%s repoPath=%s", clusterHost, parsedURL.Path)
	nodeCfg := replicas.Resolve(parsedURL)
	debuglog.Printf("entry URL: %s (used when cached replicas are empty/exhausted)", nodeCfg.EntryURL)

	token, coreURL, contextName, err := resolveCredentials(ctx, parsedURL, nodeCfg.EntryURL, clusterHost, skipTLS)
	if err != nil {
		fatal("%v", err)
	}

	onNodeFailed := makeNodeFailedHook(nodeCfg, clusterHost)
	onScopedSuccess := makeScopedSuccessHook(contextName, clusterHost)

	var scoped *auth.ScopedAuth
	var setAuth transport.SetAuthFunc
	if token != "" {
		// The repo audience slug is the URL path verbatim. STS classifies it
		// by prefix: "/et/<project>/<repo>" (or the legacy "/git/<owner>/<repo>")
		// hits validateRepoExchange against repo_urls; "/gh/<owner>/<repo>"
		// hits validateMirrorRepoExchange against github_mirror_repo_urls.
		scoped = auth.NewScoped(coreURL, token, parsedURL.Path, nodeCfg.EntryURL, newHTTPClient(skipTLS), onScopedSuccess)
		setAuth = func(req *http.Request) error {
			action := auth.GitActionFromRequest(req)
			if action == "" {
				return fmt.Errorf("cannot classify git op for %s %s; scoped-token exchange requires a recognised smart-HTTP endpoint", req.Method, req.URL.Path)
			}
			debuglog.Printf("classified %s %s as action=%s", req.Method, req.URL.Path, action)
			scopedToken, err := scoped.Get(req.Context(), action)
			if err != nil {
				return fmt.Errorf("repo-scoped token exchange: %w", err)
			}
			req.Header.Set("Authorization", "Bearer "+scopedToken)
			return nil
		}
	}

	proxy := transport.New(transport.Config{
		Nodes:        nodeCfg,
		Path:         parsedURL.Path,
		SkipTLS:      skipTLS,
		SetAuth:      setAuth,
		OnNodeFailed: onNodeFailed,
	})

	mode := githelper.ModeConnect
	if os.Getenv("ENTIRE_STATELESS") == "true" {
		debuglog.Printf("ENTIRE_STATELESS=true: advertising stateless-connect + push")
		mode = githelper.ModeStateless
	}

	if err := githelper.Run(ctx, proxy, mode, os.Stdin, os.Stdout); err != nil {
		fatal("%v", err)
	}
}

// installSignalHandler ties HTTP request lifetimes to the parent git
// process. Ctrl-C in the shell delivers SIGINT to the whole foreground
// process group, which includes us; cancelling ctx aborts in-flight
// info/refs and pack transfers instead of letting them run to the
// read timeout after the user has given up. Stdin reads
// (scanner.Scan, io.ReadFull) aren't ctx-aware — they unblock when
// git closes its stdout, which it does on SIGINT.
//
// After the first signal we unhook our handler so a second Ctrl-C
// hits the Go runtime's default disposition and hard-exits. Without
// this, signal.NotifyContext silently drops further signals, leaving
// the user with no escape hatch if graceful shutdown wedges.
//
// If we're still alive a couple of seconds after the first signal,
// surface the escape-hatch hint. Normal-exit case never reaches the
// print because main has returned and the runtime has torn the
// goroutine down.
func installSignalHandler() (context.Context, context.CancelFunc) {
	ctx, stopSignals := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	go func() {
		<-ctx.Done()
		stopSignals()
		time.Sleep(2 * time.Second)
		fmt.Fprintln(os.Stderr, "git-remote-entire: shutdown taking longer than expected; press Ctrl-C again to force-quit")
	}()
	return ctx, stopSignals
}

// resolveCredentials picks the login JWT and core URL for this
// invocation. ENTIRE_TOKEN env override takes priority (CI/workload
// identity); otherwise contexts.json + keyring drive the lookup.
//
// Returns ("", "", "", nil) when there's no credential to mint scoped
// tokens against — currently never happens, but kept for symmetry with
// future auth modes (e.g. anonymous pulls).
func resolveCredentials(ctx context.Context, parsedURL *url.URL, entryURL, clusterHost string, skipTLS bool) (token, coreURL, contextName string, err error) {
	if envToken := os.Getenv("ENTIRE_TOKEN"); envToken != "" {
		debuglog.Printf("login JWT from ENTIRE_TOKEN env override (skipping contexts.json + keyring lookup)")
		coreURL, err = auth.CoreURLFromEnvToken(envToken)
		if err != nil {
			return "", "", "", fmt.Errorf("ENTIRE_TOKEN: %w", err)
		}
		debuglog.Printf("STS endpoint from JWT aud claim: %s/api/authz/sts/token", coreURL)
		return envToken, coreURL, "", nil
	}

	configDir := auth.DefaultConfigDir()
	debuglog.Printf("reading config from %s (contexts.json maps cluster host → context, falling back to current_context)", configDir)

	httpClient := newHTTPClient(skipTLS)
	coreURL, contextName, keychainService, username, err := auth.ResolveContext(ctx, httpClient, configDir, clusterHost, debuglog.Printf)
	if err != nil {
		return "", "", "", fmt.Errorf("context resolution: %w", err)
	}
	debuglog.Printf("resolved context %q for cluster %s: handle=%s keychain=%s", contextName, clusterHost, username, keychainService)
	debuglog.Printf("loading login JWT from keyring (service=%s user=%s)", keychainService, username)

	token, err = client.GetTokenWithRefresh(ctx, client.AuthRefreshConfig{
		KeyringService: keychainService,
		BaseURL:        entryURL,
		Username:       username,
		CoreBaseURL:    coreURL,
		HTTPClient:     httpClient,
		ClientID:       clilogin.DefaultClientID,
	})
	if err != nil {
		return "", "", "", fmt.Errorf("authentication failed for %q: %w", parsedURL.String(), err)
	}
	debuglog.Printf("STS endpoint pinned to context core URL: %s/api/authz/sts/token", coreURL)
	return token, coreURL, contextName, nil
}

// makeNodeFailedHook builds the callback the transport fires when a
// cached replica fails — invalidate the on-disk cache so the next
// invocation falls back cleanly. Nil when caching is disabled.
func makeNodeFailedHook(cfg replicas.NodeConfig, clusterHost string) func(string) {
	if !cfg.Caching() {
		return nil
	}
	return func(failedNode string) {
		debuglog.Printf("cached replica %s failed, invalidating cache for %s", failedNode, cfg.RepoPath)
		replicas.Invalidate(clusterHost, cfg.RepoPath)
	}
}

// makeScopedSuccessHook builds the callback that auto-binds the
// cluster to its resolved context after the first successful STS
// exchange. Skipped under api-key and ENTIRE_TOKEN flows (no
// contextName).
func makeScopedSuccessHook(contextName, clusterHost string) func() {
	if contextName == "" {
		return nil
	}
	cfgDir := auth.DefaultConfigDir()
	return func() {
		if err := contexts.BindCluster(cfgDir, clusterHost, contextName); err != nil {
			debuglog.Printf("BindCluster %s → %s: %v", clusterHost, contextName, err)
		}
	}
}

// newHTTPClient creates an HTTP client with the given TLS
// verification setting. Used by the token-refresh path; the main
// request client is built inside the transport with a cluster-aware
// CheckRedirect.
func newHTTPClient(skipTLSVerify bool) *http.Client {
	return &http.Client{
		Timeout:   30 * time.Second,
		Transport: httpclient.NewTransport(skipTLSVerify),
	}
}

func fatal(format string, args ...any) {
	fmt.Fprintf(os.Stderr, "fatal: "+format+"\n", args...)
	os.Exit(128)
}
