1	// Package contexts is the kubectl-style context store for the Entire CLIs.
2	//
3	// One on-disk file at $ENTIRE_CONFIG_DIR/contexts.json (default
4	// ~/.config/entire/contexts.json) holds:
5	//
6	//   - a list of named contexts, each pairing a core URL, principal handle,
7	//     and OS-keychain slot where the access + refresh tokens live;
8	//   - cluster_contexts, a map from entire-server cluster host to the
9	//     context name that should authenticate ops against that cluster;
10	//   - current_context, the fallback for clusters with no binding and the
11	//     default for direct CLI commands not tied to a cluster.
12	//
13	// File invariants: 0600, atomic temp+rename, exclusive flock under load.
14	// Both CLIs share the same file so a login from either is visible to the
15	// other.
16	package contexts
17	
18	import (
19		"context"
20		"encoding/json"
21		"errors"
22		"fmt"
23		"os"
24		"path/filepath"
25		"slices"
26		"time"
27	
28		"github.com/gofrs/flock"
29	)
30	
31	// Context is a single kubectl-style entry: which core to talk to, as
32	// whom, and where the credentials are stored.
33	type Context struct {
34		// Name is the user-facing identifier. Defaults to the issuer host on
35		// auto-creation; overridable via login --name.
36		Name string `json:"name"`
37		// CoreURL is the JWT issuer URL — what STS exchanges hit. Set from
38		// the access token's signed iss claim, not the typed login URL.
39		CoreURL string `json:"core_url"`
40		// Handle is the principal handle returned from /api/auth/token.
41		Handle string `json:"handle"`
42		// KeychainService is the OS-keyring slot where the access token is
43		// filed; the refresh token lives at KeychainService+":refresh".
44		KeychainService string `json:"keychain_service"`
45	}
46	
47	// File is the on-disk shape of contexts.json.
48	type File struct {
49		// CurrentContext is the fallback for unbound clusters and the default
50		// for direct CLI commands. Empty until the first login.
51		CurrentContext string `json:"current_context,omitempty"`
52		// ClusterContexts maps entire-server cluster host → context name.
53		// Populated lazily after a successful op against the cluster, or
54		// explicitly via `entire-core context bind HOST NAME`.
55		ClusterContexts map[string]string `json:"cluster_contexts,omitempty"`
56		// Contexts is the list of stored credentials. Order is preserved on
57		// disk so list output stays stable across saves.
58		Contexts []*Context `json:"contexts,omitempty"`
59	}
60	
61	// FilePath returns $configDir/contexts.json after ensuring the directory
62	// exists with 0700 perms.
63	func FilePath(configDir string) (string, error) {
64		if err := os.MkdirAll(configDir, 0700); err != nil {
65			return "", fmt.Errorf("create config dir: %w", err)
66		}
67		return filepath.Join(configDir, "contexts.json"), nil
68	}
69	
70	// DefaultConfigDir is $ENTIRE_CONFIG_DIR if set, else ~/.config/entire.
71	func DefaultConfigDir() string {
72		if dir := os.Getenv("ENTIRE_CONFIG_DIR"); dir != "" {
73			return dir
74		}
75		home, err := os.UserHomeDir()
76		if err != nil {
77			home = "."
78		}
79		return filepath.Join(home, ".config", "entire")
80	}
81	
82	// Load reads contexts.json under configDir, returning an empty *File
83	// when the file doesn't exist yet (a fresh user). Holds an exclusive
84	// flock for the duration of the read.
85	func Load(configDir string) (*File, error) {
86		path, err := FilePath(configDir)
87		if err != nil {
88			return nil, err
89		}
90		unlock, err := lockFile(path)
91		if err != nil {
92			return nil, err
93		}
94		defer unlock()
95		return readNoLock(path)
96	}
97	
98	// Save writes f to contexts.json atomically (temp+rename) under an
99	// exclusive flock.
100	func Save(configDir string, f *File) error {
101		path, err := FilePath(configDir)
102		if err != nil {
103			return err
104		}
105		unlock, err := lockFile(path)
106		if err != nil {
107			return err
108		}
109		defer unlock()
110		return writeNoLock(path, f)
111	}
112	
113	// ContextsForIssuer returns every context whose CoreURL matches issuer
114	// after trimming. Used by CLI flows that prompt the operator when
115	// multiple sessions are stored against the same core (logout, entiredb's
116	// admin/repo prompts). Order matches the on-disk order so prompt
117	// numbering is stable across saves.
118	func (f *File) ContextsForIssuer(issuer string) []*Context {
119		if f == nil {
120			return nil
121		}
122		want := trimURL(issuer)
123		var out []*Context
124		for _, c := range f.Contexts {
125			if trimURL(c.CoreURL) == want {
126				out = append(out, c)
127			}
128		}
129		return out
130	}
131	
132	func trimURL(u string) string {
133		for len(u) > 0 && u[len(u)-1] == '/' {
134			u = u[:len(u)-1]
135		}
136		return u
137	}
138	
139	// Find returns the context with the given name, or nil.
140	func (f *File) Find(name string) *Context {
141		if f == nil || name == "" {
142			return nil
143		}
144		for _, c := range f.Contexts {
145			if c.Name == name {
146				return c
147			}
148		}
149		return nil
150	}
151	
152	// Resolve picks the context to use for an entire-server cluster. The
153	// binding wins when present and points at an existing context;
154	// otherwise we fall back to the current context. Returns nil when
155	// neither resolves.
156	func (f *File) Resolve(clusterHost string) *Context {
157		if f == nil {
158			return nil
159		}
160		if name, ok := f.ClusterContexts[clusterHost]; ok && name != "" {
161			if c := f.Find(name); c != nil {
162				return c
163			}
164			// Stale binding (context deleted out from under it). Treat as
165			// no binding rather than erroring — the current_context fallback
166			// is the safer behaviour.
167		}
168		return f.Find(f.CurrentContext)
169	}
170	
171	// Upsert replaces the context with matching Name, or appends. Sets the
172	// current context when there isn't one already (first login).
173	func (f *File) Upsert(c *Context) {
174		if c == nil || c.Name == "" {
175			return
176		}
177		for i, existing := range f.Contexts {
178			if existing.Name == c.Name {
179				f.Contexts[i] = c
180				if f.CurrentContext == "" {
181					f.CurrentContext = c.Name
182				}
183				return
184			}
185		}
186		f.Contexts = append(f.Contexts, c)
187		if f.CurrentContext == "" {
188			f.CurrentContext = c.Name
189		}
190	}
191	
192	// Delete drops the context with the given name, plus any cluster
193	// bindings that pointed at it. If the deleted context was current, the
194	// current pointer advances to whatever remains (or empty).
195	func (f *File) Delete(name string) {
196		if f == nil || name == "" {
197			return
198		}
199		idx := slices.IndexFunc(f.Contexts, func(c *Context) bool { return c.Name == name })
200		if idx >= 0 {
201			f.Contexts = slices.Delete(f.Contexts, idx, idx+1)
202		}
203		for host, target := range f.ClusterContexts {
204			if target == name {
205				delete(f.ClusterContexts, host)
206			}
207		}
208		if f.CurrentContext == name {
209			f.CurrentContext = ""
210			if len(f.Contexts) > 0 {
211				f.CurrentContext = f.Contexts[0].Name
212			}
213		}
214	}
215	
216	// Modify atomically applies fn to contexts.json under a single
217	// exclusive flock — load, mutate, write all happen with the lock held.
218	// Use this for any read-modify-write sequence; calling Load and Save
219	// separately releases the lock between them and races concurrent
220	// writers (e.g. a parallel git push triggering BindCluster).
221	//
222	// fn returns (changed, err). When changed is false the file isn't
223	// rewritten — useful for idempotent operations that often have
224	// nothing to do. When err is non-nil the change is discarded.
225	func Modify(configDir string, fn func(*File) (changed bool, err error)) error {
226		path, err := FilePath(configDir)
227		if err != nil {
228			return err
229		}
230		unlock, err := lockFile(path)
231		if err != nil {
232			return err
233		}
234		defer unlock()
235	
236		f, err := readNoLock(path)
237		if err != nil {
238			return err
239		}
240		changed, err := fn(f)
241		if err != nil {
242			return err
243		}
244		if !changed {
245			return nil
246		}
247		return writeNoLock(path, f)
248	}
249	
250	// BindCluster sets cluster_contexts[host] = name atomically. Errors
251	// when the named context doesn't exist (a stale binding is a foot-gun).
252	// Idempotent.
253	func BindCluster(configDir, host, name string) error {
254		if host == "" || name == "" {
255			return errors.New("BindCluster requires non-empty host and context name")
256		}
257		return Modify(configDir, func(f *File) (bool, error) {
258			if f.Find(name) == nil {
259				return false, fmt.Errorf("no context named %q", name)
260			}
261			if f.ClusterContexts == nil {
262				f.ClusterContexts = map[string]string{}
263			}
264			if f.ClusterContexts[host] == name {
265				return false, nil
266			}
267			f.ClusterContexts[host] = name
268			return true, nil
269		})
270	}
271	
272	func lockFile(path string) (func(), error) {
273		lockPath := path + ".lock"
274		fl := flock.New(lockPath)
275		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
276		defer cancel()
277		locked, err := fl.TryLockContext(ctx, 100*time.Millisecond)
278		if err != nil {
279			return nil, fmt.Errorf("acquire contexts lock: %w", err)
280		}
281		if !locked {
282			return nil, errors.New("timeout acquiring lock on contexts file")
283		}
284		return func() {
285			if unlockErr := fl.Unlock(); unlockErr != nil {
286				fmt.Fprintf(os.Stderr, "Warning: failed to unlock contexts file: %v\n", unlockErr)
287			}
288		}, nil
289	}
290	
291	func readNoLock(path string) (*File, error) {
292		// #nosec G304 -- path comes from ENTIRE_CONFIG_DIR or the user's home,
293		// the same trust boundary credentials.go runs under.
294		data, err := os.ReadFile(path)
295		if err != nil {
296			if os.IsNotExist(err) {
297				return &File{}, nil
298			}
299			return nil, fmt.Errorf("read contexts file: %w", err)
300		}
301		if len(data) == 0 {
302			return &File{}, nil
303		}
304		var f File
305		if err := json.Unmarshal(data, &f); err != nil {
306			return nil, fmt.Errorf("parse contexts file: %w", err)
307		}
308		return &f, nil
309	}
310	
311	func writeNoLock(path string, f *File) error {
312		data, err := json.MarshalIndent(f, "", "  ")
313		if err != nil {
314			return fmt.Errorf("marshal contexts: %w", err)
315		}
316		tmp, err := os.CreateTemp(filepath.Dir(path), ".contexts.json.tmp.*")
317		if err != nil {
318			return fmt.Errorf("create temp contexts file: %w", err)
319		}
320		tmpPath := tmp.Name()
321		cleanup := func() {
322			if tmp != nil {
323				_ = tmp.Close()
324				_ = os.Remove(tmpPath)
325			}
326		}
327		defer cleanup()
328		if _, err := tmp.Write(data); err != nil {
329			return fmt.Errorf("write temp contexts file: %w", err)
330		}
331		if err := tmp.Sync(); err != nil {
332			return fmt.Errorf("sync temp contexts file: %w", err)
333		}
334		if err := tmp.Close(); err != nil {
335			return fmt.Errorf("close temp contexts file: %w", err)
336		}
337		if err := os.Chmod(tmpPath, 0600); err != nil {
338			return fmt.Errorf("chmod temp contexts file: %w", err)
339		}
340		if err := os.Rename(tmpPath, path); err != nil {
341			return fmt.Errorf("rename temp contexts file: %w", err)
342		}
343		tmp = nil
344		return nil
345	}
346

